  "gorsel": "<table class=\"tablo\"><tr><th>Şehir</th><th>Taşıt sayısı (bin)</th><th>Yağmur suyunun pH değeri</th></tr><tr><td>K</td><td>600</td><td>4,3</td></tr><tr><td>L</td><td>300</td><td>4,9</td></tr><tr><td>M</td><td>100</td><td>5,5</td></tr></table>",
